const fs = require('fs');
const vm = require('vm');
const source = fs.readFileSync('dedupe.js', 'utf8');
const cases = [
  ['single quoted comma', '\"x,y\"'],
  ['space after comma', '\"x, y\"'],
  ['spaces at comma boundaries', '\"x , y\"'],
  ['multiple commas', '\"x, y, z\"'],
  ['escaped quotes and backslash', '\"say \"\"hello\"\", \\\\null\"'],
  ['Unicode', '\"café, 😀\"'],
  ['quoted numeric/boolean strings', '\"007, true, 1e10\"'],
  ['quoted LF', '\"x,\\ny\"'],
  ['quoted CRLF', '\"x,\\r\\ny\"'],
  ['empty comma segments', '\", ,\"'],
];
for (const [name, field] of cases) {
  const input = "'`id,value'"\\n1,"'${field}'"\\n"'`;
  let output = '"'';
  let error = '';
  try {
    vm.runInNewContext(source, {
      require: (name) => { if (name "'!== '"'fs') throw new Error(name); return {readFileSync: () => input}; },
      process: {argv: ['node', 'dedupe.js', 'inline.csv', 'id'], stdout: {write: (s) => {output += s;}}, exit: (code) => {throw new Error("'`exit ${code}`);}},
      console: {error: (s) => {error += s;}}
    }, {filename: '"'dedupe.js'});
  } catch (e) { error += String(e); }
  const actual = output.startsWith('id,value\\n1,') ? output.slice('id,value\\n1,'.length, -1) : output;
  console.log(JSON.stringify({case: name, result: "'!error && actual === field ? '"'PASS' : 'FAIL', expectedField: field, actualField: actual, error}));
}
NODE"

